-- 1300_papasud_datos_reales.sql
-- Requiere: ALTER TABLE pap_insumos ADD COLUMN IF NOT EXISTS precio_usd numeric(12,4);

-- El mismo número de lote existe en los dos pivotes (L55 está en el A y en el B):
-- son sectores distintos del campo. La unicidad va por lote Y pivote.
ALTER TABLE pap_parcelas DROP CONSTRAINT IF EXISTS pap_parcelas_org_id_codigo_key;
CREATE UNIQUE INDEX IF NOT EXISTS pap_parcelas_org_codigo_pivote
  ON pap_parcelas (org_id, codigo, COALESCE(pivote, ''));
--
-- Datos REALES de Papasud, extraídos de sus propios archivos:
--   · Plano_Santa_Ana_2023.pdf          → los lotes por pivote, cuadrante y tercio
--   · Orden_de_trabajo.xlsx             → 3 órdenes de aplicación y el catálogo de agroquímicos
--   · Planilla_de_movimientos_2026.xls  → 436 movimientos de stock de la campaña 2026
--
-- Reemplaza el dataset sintético anterior. Es idempotente: borra lo de Papasud
-- y lo vuelve a insertar.

\set ON_ERROR_STOP on

ALTER TABLE pap_insumos ADD COLUMN IF NOT EXISTS precio_usd numeric(12,4);

-- El mismo número de lote existe en los dos pivotes (L55 está en el A y en el B):
-- son sectores distintos del campo. La unicidad va por lote Y pivote.
ALTER TABLE pap_parcelas DROP CONSTRAINT IF EXISTS pap_parcelas_org_id_codigo_key;
CREATE UNIQUE INDEX IF NOT EXISTS pap_parcelas_org_codigo_pivote
  ON pap_parcelas (org_id, codigo, COALESCE(pivote, ''));

-- Movimientos de stock tal como los lleva Papasud. El modelo de transferencias
-- heredado no alcanza: acá manda el remito, el DTV de SENASA, la bolsa como
-- unidad y el color de bolsa e hilo, que es como se identifica en el galpón.
CREATE TABLE IF NOT EXISTS pap_movimientos (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL,
  tipo         varchar(30) NOT NULL,   -- campo_a_frio / ingreso_tolvas / envio_a_frio /
                                       -- retiro_de_frio / ingreso_trevelin / entrega_a_cliente
  remito       varchar(30),
  fecha        date,
  variedad_id  uuid REFERENCES pap_variedades(id) ON DELETE SET NULL,
  variedad     varchar(60),
  lote         varchar(20),
  categoria    varchar(60),            -- inicial 1/2/3, cámara 2/3, repasada
  calibre      varchar(40),            -- exportacion / sin chicas / recibo / granel
  bolsas       numeric(10,1),
  kgs          numeric(12,1),
  kg_promedio  numeric(8,2),           -- kilos por bolsa
  transporte   varchar(120),
  destino      varchar(60),
  color_bolsa  varchar(30),
  color_hilo   varchar(30),
  dtv          varchar(30),            -- Documento de Tránsito Vegetal (SENASA)
  observaciones text,
  created_at   timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pap_mov_org     ON pap_movimientos(org_id);
CREATE INDEX IF NOT EXISTS idx_pap_mov_fecha   ON pap_movimientos(fecha DESC);
CREATE INDEX IF NOT EXISTS idx_pap_mov_lote    ON pap_movimientos(lote);
CREATE INDEX IF NOT EXISTS idx_pap_mov_tipo    ON pap_movimientos(tipo);

